    method Multiply(a, b) {
        acc = 0
        sign = 0
        if (b < 0) {
            b = 0 - b
            sign = sign + 1
        }
        if (a < 0) {
            a = 0 - a
            sign = sign + 1
        }
        while (b > 0) {
            low = bfext(b, 0, 1)
            if (low == 1) {
                acc = acc + a
            }
            a = a << 1
            b = b >> 1
        }
        if (sign == 1) {
            acc = 0 - acc
        }
        return(acc)
    }

    method Divide(a, b) {
        if (b == 0) {
            return(0)
        }
        sign = 0
        if (a < 0) {
            a = 0 - a
            sign = sign + 1
        }
        if (b < 0) {
            b = 0 - b
            sign = sign + 1
        }
        quot = 0
        while (a >= b) {
            a = a - b
            quot = quot + 1
        }
        if (sign == 1) {
            quot = 0 - quot
        }
        return(quot)
    }

    method Sqrt(n) {
        if (n == 0) {
            return(0)
        }
        if (n == 1) {
            return(1)
        }
        res = 0
        bit = 16384
        while (bit > 0) {
            test = res + bit
            if (n >= test) {
                n = n - test
                res = res >> 1
                res = res + bit
            } else {
                res = res >> 1
            }
            bit = bit >> 2
        }
        return(res)
    }

    method Mod(a, b) {
